describe('listing conversations', () => {
  it('answers list_sessions for the session user with ISO dates, forwarding limit and before, and answers empty when listFor is absent', async () => {
    const orchestrator = {} as ChatOrchestrator;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const created = new Date('2026-02-10T08:00:00.000Z');
    const updated = new Date('2026-02-10T09:15:00.000Z');
    const calls: Array<[string | number, SessionListOptions | undefined]> = [];
    const listingStore = {
      listFor: (userId: string | number, options?: SessionListOptions): SessionSummary[] => {
        calls.push([userId, options]);
        return [{sessionId: 'conv-1', createdAt: created, updatedAt: updated, entryCount: 7}];
      },
    } as unknown as SessionStore;

    const sendTo = async (store: SessionStore | undefined, frame: unknown): Promise<OutgoingMessage[]> => {
      const out: OutgoingMessage[] = [];
      const socket = {
        send: (raw: string) => void out.push(JSON.parse(raw) as OutgoingMessage),
      } as unknown as WebSocket;
      await createMessageHandler(orchestrator, store)(socket, session, frame);
      return out;
    };

    const before = {updatedAt: '2026-02-10T10:00:00.000Z', sessionId: 'conv-2'};
    const expectedList: OutgoingMessage = {
      type: 'session_list',
      sessions: [{sessionId: 'conv-1', createdAt: created.toISOString(), updatedAt: updated.toISOString(), entryCount: 7}],
    };

    expect({
      listed: await sendTo(listingStore, {type: 'list_sessions', limit: 10, before, userId: 'u2'}),
      bare: await sendTo(listingStore, {type: 'list_sessions'}),
      fromPlain: await sendTo({} as SessionStore, {type: 'list_sessions'}),
      fromOmitted: await sendTo(undefined, {type: 'list_sessions'}),
      calls,
    }).toEqual({
      listed: [expectedList],
      bare: [expectedList],
      fromPlain: [{type: 'session_list', sessions: []}],
      fromOmitted: [{type: 'session_list', sessions: []}],
      calls: [
        ['u1', {limit: 10, before}],
        ['u1', {}],
      ],
    });
  });

